SELECT * FROM ( SELECT TKSM.TOKUISAKICD TOKUISAKICD , TKSM.TOKUISAKINMN1 TOKUISAKINMN1 , TKSM.TOKUISAKINMN2 TOKUISAKINMN2 , TKSM.YUBINNO YUBINNO , TKSM.RENRAKUSAKINON1 RENRAKUSAKINON1 , TKSM.ADRSN1 ADRSN1 , TKSM.ADRSN2 ADRSN2 , TKSM.ADRSN3 ADRSN3 , TKSM.JUTAKUDLVRYCSTKBN JUTAKUDLVRYCSTKBN , TJST.ZNKDLVRYDD ZNKDLVRYDD , TJST.ZZKHTDD ZZKHTDD , TJST.ZZZKHTDD ZZZKHTDD , ( NVL(TJST.ZNKDLVRYRGRAYUSYOHNS,0) + NVL(TJST.ZNKDLVRYRGRAMUSHOHNS,0) + NVL(TJST.ZNKDLVRYSRMYUSYOHNS,0) + NVL(TJST.ZNKDLVRYSRMMUSHOHNS,0) + NVL(TJST.ZNKDLVRYSONOTAYUSYOHNS,0) + NVL(TJST.ZNKDLVRYSONOTAMUSHOHNS,0) ) NOHINHNSMEI1 , ( NVL(TJST.ZZKHTRGRAYUSYOHNS,0) + NVL(TJST.ZZKHTRGRAMUSHOHNS,0) + NVL(TJST.ZZKHTSRMYUSYOHNS,0) + NVL(TJST.ZZKHTSRMMUSHOHNS,0) + NVL(TJST.ZZKHTSONOTAYUSYOHNS,0) + NVL(TJST.ZZKHTSONOTAMUSHOHNS,0) ) AS NOHINHNSMEI2 , ( NVL(TJST.ZZZKHTRGRAYUSYOHNS,0) + NVL(TJST.ZZZKHTRGRAMUSHOHNS,0) + NVL(TJST.ZZZKHTSRMYUSYOHNS,0) + NVL(TJST.ZZZKHTSRMMUSHOHNS,0) + NVL(TJST.ZZZKHTSONOTAYUSYOHNS,0) + NVL(TJST.ZZZKHTSONOTAMUSHOHNS,0) ) AS NOHINHNSMEI3 , SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD , SHMV.GENZSHNNMRYAKUSHO GENZSHNNMRYAKUSHO , SHMV.SHINSHNNMRYAKUSHO SHINSHNNMRYAKUSHO , DECODE(TKSM10.SHNCD, NULL, NULL, TKSM10.STUPDD) STUPDD , DECODE(TKSM10.SHNCD, NULL, NULL, TKSM10.JIKAIMNTYTIDYDM) JIKAIMNTYTIDYDM ,( SELECT COUNT(*) FROM S02M048T TSSM WHERE TSSM.APKIHONCD = TKSM10.APKIHONCD AND TSSM.SHOPCD = TKSM10.SHOPCD AND TSSM.TOKUISAKICD = TKSM10.TOKUISAKICD AND TSSM.SHNCD = TKSM10.SHNCD AND TSSM.HIKIAGEDD IS NULL AND TSSM.YUKOKBN = '1' ) WSVSTUPDAISUMEI ,( SELECT COUNT(*) FROM S02M048T TSSM2 WHERE TSSM2.APKIHONCD = TKSM10.APKIHONCD AND TSSM2.SHOPCD = TKSM10.SHOPCD AND TSSM2.TOKUISAKICD = TKSM10.TOKUISAKICD AND TSSM2.SHNCD != TKSM10.SHNCD AND TSSM2.HIKIAGEDD IS NULL AND TSSM2.YUKOKBN = '1' ) WSVDAISUMEI , JGSM.JIGYOSHONM JIGYOSHONM , TTSM.TNSHAMEI TNSHAMEI FROM S02M013T TKSM LEFT JOIN S02M047T JGSM ON ( TKSM.APKIHONCD = JGSM.APKIHONCD AND TKSM.SHOPCD = JGSM.SHOPCD AND TKSM.JIGYOSHOCD = JGSM.JIGYOSHOCD ) LEFT JOIN S02M003T TTSM ON ( TKSM.APKIHONCD = TTSM.APKIHONCD AND TKSM.SHOPCD = TTSM.SHOPCD AND TKSM.EIGYOTNSHACD = TTSM.TNSHACD ) LEFT JOIN ( SELECT S02M048T.APKIHONCD , S02M048T.SHOPCD , S02M048T.TOKUISAKICD , S02M048T.STUPWSVNO , S02M048T.SHNCD , S02M048T.STUPDD , S02M048T.JIKAIMNTYTIDYDM FROM S02M048T ,( SELECT APKIHONCD , SHOPCD , TOKUISAKICD , MIN(STUPWSVNO) STUPWSVNO FROM S02M048T WHERE HIKIAGEDD IS NULL
AND APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
GROUP BY APKIHONCD , SHOPCD , TOKUISAKICD ) SUB1 WHERE S02M048T.APKIHONCD = SUB1.APKIHONCD AND S02M048T.SHOPCD = SUB1.SHOPCD AND S02M048T.TOKUISAKICD = SUB1.TOKUISAKICD AND S02M048T.STUPWSVNO = SUB1.STUPWSVNO ) TKSM10 ON ( TKSM10.APKIHONCD = TKSM.APKIHONCD AND TKSM10.SHOPCD = TKSM.SHOPCD AND TKSM10.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT JOIN S02V001T SHMV ON (SHMV.APKIHONCD = TKSM10.APKIHONCD AND SHMV.SHOPCD = TKSM10.SHOPCD AND SHMV.SHNCD = TKSM10.SHNCD ) JOIN S02M017T SKSM ON ( TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD ) JOIN S02M050T TJST ON ( TJST.APKIHONCD = TKSM.APKIHONCD AND TJST.SHOPCD = TKSM.SHOPCD AND TJST.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT JOIN S04T001T JHTT ON ( JHTT.APKIHONCD = TJST.APKIHONCD AND JHTT.SHOPCD = TJST.SHOPCD AND JHTT.ACPTDNPYNO = TJST.ZNKDLVRYDNPYNO AND JHTT.EDANO = TJST.ZNKDLVRYDNPYEDANO ) WHERE TJST.ZNKDLVRYDNPYNO IS NOT NULL AND TJST.YUKOKBN = '1' AND TKSM.TOKUISAKIJOTAI IN ('3', '5') AND TKSM.TOKUISAKIKBN = '1' AND TKSM.KYUMINKANRI = '1'
