SELECT
    TKSM.TOKUISAKICD
   ,TKSM.DLVRYTNSHACD
   ,TKSM.TOKUISAKIJOTAI
   ,TTSM.TNSHAMEI
   ,TKSM.ACPTJIKANSHITEIJIKOKU
   ,SYKM1.MOJISETTEIATAI ACPTJIKANSHITEIKBNNM
   ,FOKFLG.ITEMNM FZAIOKIKANOFLGNM
   ,SYKM2.MOJISETTEIATAI NOHINSAKIJOHON1NM
   ,SYKM3.MOJISETTEIATAI NOHINSAKIJOHON2NM
   ,TKSM.KSHNSYSTMYMD
   ,TKSM.KSHNSYSTMJIKAN
FROM
    S02M013T TKSM
LEFT JOIN S02M003T TTSM
 ON TTSM.APKIHONCD = TKSM.APKIHONCD
AND TTSM.SHOPCD = TKSM.SHOPCD
AND TTSM.TNSHACD = TKSM.DLVRYTNSHACD
LEFT JOIN S02M006T SYKM1
 ON SYKM1.APKIHONCD = #{constapkihoncd000,jdbcType=VARCHAR}
AND SYKM1.SHOPCD = #{constshopcd000,jdbcType=VARCHAR}
AND SYKM1.SETTEINO = #{constsetteino012,jdbcType=VARCHAR}
AND SYKM1.RCRDKBN = #{constrecordkbnm,jdbcType=VARCHAR}
AND SYKM1.SETTEICD = TKSM.ACPTJIKANSHITEIKBN
LEFT JOIN S02M006T SYKM2
 ON SYKM2.APKIHONCD = #{constapkihoncd000,jdbcType=VARCHAR}
AND SYKM2.SHOPCD = #{constshopcd000,jdbcType=VARCHAR}
AND SYKM2.SETTEINO = #{constsetteino056,jdbcType=VARCHAR}
AND SYKM2.RCRDKBN = #{constrecordkbnm,jdbcType=VARCHAR}
AND SYKM2.SETTEICD = TKSM.NOHINSAKIJOHON1
LEFT JOIN S02M006T SYKM3
 ON SYKM3.APKIHONCD = #{constapkihoncd000,jdbcType=VARCHAR}
AND SYKM3.SHOPCD = #{constshopcd000,jdbcType=VARCHAR}
AND SYKM3.SETTEINO = #{constsetteino057,jdbcType=VARCHAR}
AND SYKM3.RCRDKBN = #{constrecordkbnm,jdbcType=VARCHAR}
AND SYKM3.SETTEICD = TKSM.NOHINSAKIJOHON2
LEFT JOIN S01M004T FOKFLG
 ON FOKFLG.CONDITIONID = 'CN043'
AND FOKFLG.SETTEIATAI = TKSM.FZAIOKIKANOFLG
WHERE
    TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}

SELECT TKS.* , URI.* , NK.* , ZD.* , (NVL(URI.SEIHINMIZUURI, 0) + NVL(URI.RTLRKN, 0) + NVL(URI.SONOTAURIKIN, 0)) TOTSUKIURIKEIMEI , (NVL(ZD.ZNKKURIKOSHIKIN, 0) + (NVL(URI.SEIHINMIZUURI, 0) + NVL(URI.RTLRKN, 0) + NVL(URI.SONOTAURIKIN, 0)) + NVL(URI.KONKAISHOHITAXKIN, 0) - NVL(NK.KONKAINYKNKIN, 0)) KURIKOSHIKIN FROM ( SELECT TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.TOKUISAKICD , TKSM.TOKUISAKINMN1 , TKSM.EIGYOTNSHACD , TTSM.TNSHAMEI , TKSM.JOTAISTS , TKSM.TOKUISAKIKBN , TKSM.JUTAKUDLVRYCSTKBN , TKSM.SKYSAKICD , TKSM.HONBUEJNTCD , TKSM.KAKUTOKUEJNTCD , SYKM1.MOJISETTEIATAI TOKUISAKIJOTAINM , SYKM2.MOJISETTEIATAI JOTAISTSNM , TKSM.TOKUISAKIJOTAI , TSKB.ITEMNM TOKUISAKIKBNNM , JDKB.ITEMNM JUTAKUDLVRYCSTKBNNM , ( CASE WHEN TKSM.TOKUISAKIJOTAI = '5' THEN '' WHEN TKSM.TOKUISAKIJOTAI <> '5' THEN ( SELECT MOJISETTEIATAI FROM S02M006T WHERE APKIHONCD(+) = '000' AND SHOPCD(+) = '000' AND SETTEINO(+) = '014' AND RCRDKBN(+) = 'M' AND SETTEICD(+) = TKSM.TOKUISAKIJOTAI ) END ) JOTAINMN , TKSM.RIYOWSVKBN , SYKM3.MOJISETTEIATAI RIYOWSVKBNNM , TKSM.JIGYOSHOCD , JGSM.JIGYOSHONM , SHPM.SHOPNM SHOPNM FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) LEFT JOIN S02M047T JGSM ON ( JGSM.APKIHONCD = TKSM.APKIHONCD AND JGSM.SHOPCD = TKSM.SHOPCD AND JGSM.JIGYOSHOCD = TKSM.JIGYOSHOCD ) LEFT JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '014' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = TKSM.TOKUISAKIJOTAI AND SYKM1.YUKOKBN = '1' ) LEFT JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '015' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = TKSM.JOTAISTS AND SYKM2.YUKOKBN = '1' ) LEFT JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '167' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = TKSM.RIYOWSVKBN AND SYKM3.YUKOKBN = '1' ) LEFT JOIN S02M003T TTSM ON ( TTSM.APKIHONCD = TKSM.APKIHONCD AND TTSM.SHOPCD = TKSM.SHOPCD AND TTSM.TNSHACD = TKSM.EIGYOTNSHACD ) LEFT JOIN S01M004T TSKB ON ( TSKB.CONDITIONID = 'CN100' AND TSKB.SETTEIATAI = TKSM.TOKUISAKIKBN ) LEFT JOIN S01M004T JDKB ON ( JDKB.CONDITIONID = 'CN206' AND JDKB.SETTEIATAI = TKSM.JUTAKUDLVRYCSTKBN ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN IN
#{tokuisakikbnlist}
) TKS LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD_UR , TKSM.SHOPCD SHOPCD_UR , TKSM.TOKUISAKICD TOKUISAKICD_UR , SUM( CASE WHEN URMT.SHNCD IN ( SELECT RGR.SHNCD FROM S02M007T RGR WHERE RGR.APKIHONCD(+) = '001' AND STKBN(+) = '0' AND LCTGRYCD(+) = '01' AND MCTGRYCD(+) = '001' AND SCTGRYCD(+) = '001' AND YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) RGRAYURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT RGR.SHNCD FROM S02M007T RGR WHERE RGR.APKIHONCD(+) = '001' AND RGR.STKBN(+) = '0' AND RGR.LCTGRYCD(+) = '01' AND RGR.MCTGRYCD(+) = '001' AND RGR.SCTGRYCD(+) = '001' AND RGR.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) RGRAMURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT SRM.SHNCD FROM S02M007T SRM WHERE SRM.APKIHONCD(+) = '001' AND SRM.STKBN(+) = '0' AND SRM.LCTGRYCD(+) = '01' AND SRM.MCTGRYCD(+) = '001' AND SRM.SCTGRYCD(+) = '002' AND SRM.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SRMYURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT SRM.SHNCD FROM S02M007T SRM WHERE SRM.APKIHONCD(+) = '001' AND SRM.STKBN(+) = '0' AND SRM.LCTGRYCD(+) = '01' AND SRM.MCTGRYCD(+) = '001' AND SRM.SCTGRYCD(+) = '002' AND SRM.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SRMMURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) AND URMT.SHNCD NOT IN ( SELECT SNT.SHNCD FROM S02M007T SNT WHERE SNT.APKIHONCD(+) = '001' AND SNT.STKBN(+) = '0' AND SNT.LCTGRYCD(+) = '01' AND SNT.MCTGRYCD(+) = '001' AND SNT.SCTGRYCD IN ('001', '002') AND SNT.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SONOTAYURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) AND URMT.SHNCD NOT IN ( SELECT SNT.SHNCD FROM S02M007T SNT WHERE SNT.APKIHONCD(+) = '001' AND SNT.STKBN(+) = '0' AND SNT.LCTGRYCD(+) = '01' AND SNT.MCTGRYCD(+) = '001' AND SNT.SCTGRYCD IN ('001', '002') AND SNT.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SONOTAMURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SEIHINMIZUURI , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD IN ( SELECT SVR.MOJISETTEIATAI FROM S02M006T SVR WHERE SVR.APKIHONCD(+) = '000' AND SVR.SHOPCD(+) = '000' AND SVR.SETTEINO(+) = '096' AND SVR.RCRDKBN(+) = 'M' AND SVR.SETTEICD IN ('2', '3') AND SVR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) RTLRKN , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD NOT IN ( SELECT SNT.MOJISETTEIATAI FROM S02M006T SNT WHERE SNT.APKIHONCD(+) = '000' AND SNT.SHOPCD(+) = '000' AND SNT.SETTEINO(+) = '096' AND SNT.RCRDKBN(+) = 'M' AND SNT.SETTEICD IN ('1', '2', '3') AND SNT.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SONOTAURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHOHITAXKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) KONKAISHUNODAIKOURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHUNODAIKOSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.KIN ELSE 0 END ) N8PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.SHOHITAXKIN ELSE 0 END ) N8PERSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.KIN ELSE 0 END ) N10PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) N10PERSHOHITAXKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S06T001T URHT ON ( URHT.APKIHONCD = TKSM.APKIHONCD AND URHT.SHOPCD = TKSM.SHOPCD AND URHT.TOKUISAKICD = TKSM.TOKUISAKICD AND URHT.GETSUJIPRCSJISSIDD = '00000000' AND URHT.URIDD <= #{dydm,jdbcType=VARCHAR} || SHPM.SHIMEDD AND URHT.YUKOKBN = '1' ) INNER JOIN S06T002T URMT ON ( URMT.APKIHONCD = URHT.APKIHONCD AND URMT.SHOPCD = URHT.SHOPCD AND URMT.URIDNPYNO = URHT.URIDNPYNO AND URMT.EDANO = URHT.EDANO AND URMT.YUKOKBN = '1' ) LEFT OUTER JOIN S02M091T ZEI ON ( URMT.TAXKBN = ZEI.TAXKBN AND URHT.URIDD BETWEEN ZEI.TEKIYOSTRTDD AND ZEI.TEKIYOSHRYDD AND ZEI.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
