AND TTSM.SHOPCD = TKSM.SHOPCD AND TTSM.TNSHACD = TKSM.EIGYOTNSHACD ) LEFT JOIN S01M004T TSKB ON ( TSKB.CONDITIONID = 'CN100' AND TSKB.SETTEIATAI = TKSM.TOKUISAKIKBN ) LEFT JOIN S01M004T JDKB ON ( JDKB.CONDITIONID = 'CN206' AND JDKB.SETTEIATAI = TKSM.JUTAKUDLVRYCSTKBN ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
