 WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) AND URMT.SHNCD NOT IN ( SELECT SNT.SHNCD FROM S02M007T SNT WHERE SNT.APKIHONCD(+) = '001' AND SNT.STKBN(+) = '0' AND SNT.LCTGRYCD(+) = '01' AND SNT.MCTGRYCD(+) = '001' AND SNT.SCTGRYCD IN ('001', '002') AND SNT.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SONOTAMURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SEIHINMIZUURI , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD IN ( SELECT SVR.MOJISETTEIATAI FROM S02M006T SVR WHERE SVR.APKIHONCD(+) = '000' AND SVR.SHOPCD(+) = '000' AND SVR.SETTEINO(+) = '096' AND SVR.RCRDKBN(+) = 'M' AND SVR.SETTEICD IN ('2', '3') AND SVR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) RTLRKN , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD NOT IN ( SELECT SNT.MOJISETTEIATAI FROM S02M006T SNT WHERE SNT.APKIHONCD(+) = '000' AND SNT.SHOPCD(+) = '000' AND SNT.SETTEINO(+) = '096' AND SNT.RCRDKBN(+) = 'M' AND SNT.SETTEICD IN ('1', '2', '3') AND SNT.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SONOTAURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHOHITAXKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) KONKAISHUNODAIKOURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHUNODAIKOSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.KIN ELSE 0 END ) N8PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.SHOHITAXKIN ELSE 0 END ) N8PERSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.KIN ELSE 0 END ) N10PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) N10PERSHOHITAXKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S06T001T URHT ON ( URHT.APKIHONCD = TKSM.APKIHONCD AND URHT.SHOPCD = TKSM.SHOPCD AND URHT.TOKUISAKICD = TKSM.TOKUISAKICD AND URHT.GETSUJIPRCSJISSIDD = '00000000' AND URHT.URIDD <= #{dydm,jdbcType=VARCHAR} || SHPM.SHIMEDD AND URHT.YUKOKBN = '1' ) INNER JOIN S06T002T URMT ON ( URMT.APKIHONCD = URHT.APKIHONCD AND URMT.SHOPCD = URHT.SHOPCD AND URMT.URIDNPYNO = URHT.URIDNPYNO AND URMT.EDANO = URHT.EDANO AND URMT.YUKOKBN = '1' ) LEFT OUTER JOIN S02M091T ZEI ON ( URMT.TAXKBN = ZEI.TAXKBN AND URHT.URIDD BETWEEN ZEI.TEKIYOSTRTDD AND ZEI.TEKIYOSHRYDD AND ZEI.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}