) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) KONKAISHUNODAIKOURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHUNODAIKOSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.KIN ELSE 0 END ) N8PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '4' THEN URMT.SHOHITAXKIN ELSE 0 END ) N8PERSHOHITAXKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.KIN ELSE 0 END ) N10PERTAXNUKIURIKIN ,SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.TAXKBN = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) N10PERSHOHITAXKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S06T001T URHT ON ( URHT.APKIHONCD = TKSM.APKIHONCD AND URHT.SHOPCD = TKSM.SHOPCD AND URHT.TOKUISAKICD = TKSM.TOKUISAKICD AND URHT.GETSUJIPRCSJISSIDD = '00000000' AND URHT.URIDD <= #{dydm,jdbcType=VARCHAR} || SHPM.SHIMEDD AND URHT.YUKOKBN = '1' ) INNER JOIN S06T002T URMT ON ( URMT.APKIHONCD = URHT.APKIHONCD AND URMT.SHOPCD = URHT.SHOPCD AND URMT.URIDNPYNO = URHT.URIDNPYNO AND URMT.EDANO = URHT.EDANO AND URMT.YUKOKBN = '1' ) LEFT OUTER JOIN S02M091T ZEI ON ( URMT.TAXKBN = ZEI.TAXKBN AND URHT.URIDD BETWEEN ZEI.TEKIYOSTRTDD AND ZEI.TEKIYOSHRYDD AND ZEI.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}