SELECT * FROM ( SELECT TKSM.APKIHONCD ,TKSM.SHOPCD ,TKSM.TOKUISAKICD ,STKM1.MOJISETTEIATAI AS TOKUISAKIJOTAI ,STKM2.MOJISETTEIATAI AS JOTAISTS ,STKM3.MOJISETTEIATAI AS CDKINDKBN ,STKM4.MOJISETTEIATAI AS GYOSHUKBN ,STKM5.MOJISETTEIATAI AS RCPTKBN ,STKM6.MOJISETTEIATAI AS KAKUTOKUKBN ,STKM7.MOJISETTEIATAI AS BAITAIKBN ,STKM8.MOJISETTEIATAI AS TAIKAIRIYUKBN ,STKM9.MOJISETTEIATAI AS CHUITOKUISAKIKBNAP ,STKM10.MOJISETTEIATAI AS TOKUBETSUUNTKBNNM ,TKSM.TOKUISAKINMN1 ,TKSM.TOKUISAKINMKANAN1 ,TKSM.RENRAKUSAKINON1 ,DECODE(SIGN(( SELECT COUNT(*) FROM S02M013T TKSM2 WHERE TKSM2.APKIHONCD = TKSM.APKIHONCD AND TKSM2.SHOPCD = TKSM.SHOPCD AND TKSM2.TOKUISAKINMN1 = TKSM.TOKUISAKINMN1 )-1),1, '1', '0') AS DOSEIDOUMEI ,TKSM.YUBINNO ,TKSM.ADRSN1 ,TKSM.ADRSN2 ,TKSM.SKYSAKICD ,TKSM.TOKUISAKIGAIBUSKBTSCD ,HTAM.DLVRYAREACD ,HTAM.DLVRYAREANM ,SKSM.TAIRYUKBN ,CNDM3.ITEMNM AS TAIRYUKBNNM ,TKSM.SHOKAIWSVSTUPDD ,TKSM.NYUKAIDD ,TKSM.TAIKAIDD ,TKSM.TOKUISAKIKBN ,CNDM1.ITEMNM AS TOKUISAKIKBNNM ,TKSM.JUTAKUDLVRYCSTKBN ,CNDM2.ITEMNM AS JUTAKUDLVRYCSTKBNNM ,TKSM.TOKUISAKISHOPCD ,TKSM.JIGYOSHOCD ,JGSM.JIGYOSHONM ,TKSM.TOKUISAKISHUKEICD ,TKSM.TOKUISAKINMN2 ,TKSM.ADRSN3 ,TKSM.RENRAKUSAKINON2 ,TKSM.RENRAKUSAKINON3 ,TKSM.RENRAKUSAKINON4 ,TKSM.HANSOKUSHSCD ,TKSM.KAKUTOKUSHSMEMO ,TKSM.EIGYOAREACD ,EIAM.EIGYOAREANM ,TKSM.EIGYOTNSHACD ,TKSM.KAKUTOKUEJNTCD ,TKSM.MOSHIKOMIRCPTDD ,TKSM.MOSHIKOMICNCLDD ,TKSM.WSVHIKIAGEDD ,TKSM.TAIKAIRIYUSHS ,TKSM.KEIZOKURNK ,TKSM.SHOHIRNK ,TKSM.APBETSUTOKUISAKIRNK ,DECODE(TKSM.KYUMINKBN,'1','休眠','なし') AS KYUMINKBN ,TKSM.TOKUBETSUUNTKBN ,TNTM.BUSHOCD ,BSHM.BUSHONM ,TKSM.DLVRYKANKATSUAPKIHONCD ,TKSM.DLVRYKANKATSUSHOPCD ,TKSM.DLVRYKANKATSUKYOTENCD ,TKSM.DLVRYCMPNYCD ,TKSM.DLVRYTNSHACD ,TKSM.DLVRYKBN ,CNDM4.ITEMNM AS DLVRYKBNNM ,TKSM.GAIBURENKEIDLVRYCD ,TKSM.ACPTRCPTKBN ,CNDM5.ITEMNM AS ACPTRCPTKBNNM ,TKSM.TOSHACD ,TKSM.INPTSYSTMYMD ,TKSM.INPTSYSTMJIKAN ,TKSM.INPTPGMID ,TKSM.KOSHACD ,TKSM.KSHNSYSTMYMD ,TKSM.KSHNSYSTMJIKAN ,TKSM.KSHNPGMID ,TKSM.MTMKISVKBN ,TKSM.MTMKIYURYOHNS ,TKSM.MTMKIMURYOHNS ,TKSM.MURYOBTLSVKBN ,TKSM.YUKOKBN ,CNDM6.ITEMNM AS YUKOKBNNM ,'1' AS HONBUCLCRENKEIKBN FROM S02M013T TKSM LEFT OUTER JOIN S02M017T SKSM ON ( SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M003T TNTM ON ( TNTM.APKIHONCD = TKSM.APKIHONCD AND TNTM.SHOPCD = TKSM.SHOPCD AND TNTM.TNSHACD = TKSM.EIGYOTNSHACD ) LEFT OUTER JOIN S02M002T BSHM ON ( BSHM.APKIHONCD = TNTM.APKIHONCD AND BSHM.SHOPCD = TNTM.SHOPCD AND BSHM.BUSHOCD = TNTM.BUSHOCD ) LEFT OUTER JOIN S02M050T TSJT ON ( TSJT.APKIHONCD = TKSM.APKIHONCD AND TSJT.SHOPCD = TKSM.SHOPCD AND TSJT.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT OUTER JOIN S02M006T STKM1 ON ( STKM1.APKIHONCD = '000' AND STKM1.SHOPCD = '000' AND STKM1.SETTEINO = '014' AND STKM1.RCRDKBN = 'M' AND STKM1.SETTEICD = TKSM.TOKUISAKIJOTAI ) LEFT OUTER JOIN S02M006T STKM2 ON ( STKM2.APKIHONCD = '000' AND STKM2.SHOPCD = '000' AND STKM2.SETTEINO = '015' AND STKM2.RCRDKBN = 'M' AND STKM2.SETTEICD = TKSM.JOTAISTS ) LEFT OUTER JOIN S02M006T STKM3 ON ( STKM3.APKIHONCD = '000' AND STKM3.SHOPCD = '000' AND STKM3.SETTEINO = '016' AND STKM3.RCRDKBN = 'M' AND STKM3.SETTEICD = TKSM.CDKINDKBN ) LEFT OUTER JOIN S02M006T STKM4 ON ( STKM4.APKIHONCD = '000' AND STKM4.SHOPCD = '000' AND STKM4.SETTEINO = '017' AND STKM4.RCRDKBN = 'M' AND STKM4.SETTEICD = TKSM.GYOSHUKBN ) LEFT OUTER JOIN S02M006T STKM5 ON ( STKM5.APKIHONCD = '000' AND STKM5.SHOPCD = '000' AND STKM5.SETTEINO = '018' AND STKM5.RCRDKBN = 'M' AND STKM5.SETTEICD = TKSM.RCPTKBN ) LEFT OUTER JOIN S02M006T STKM6 ON ( STKM6.APKIHONCD = '000' AND STKM6.SHOPCD = '000' AND STKM6.SETTEINO = '019' AND STKM6.RCRDKBN = 'M' AND STKM6.SETTEICD = TKSM.KAKUTOKUKBN ) LEFT OUTER JOIN S02M006T STKM7 ON ( STKM7.APKIHONCD = '000' AND STKM7.SHOPCD = '000' AND STKM7.SETTEINO = '020' AND STKM7.RCRDKBN = 'M' AND STKM7.SETTEICD = TKSM.BAITAIKBN ) LEFT OUTER JOIN S02M006T STKM8 ON ( STKM8.APKIHONCD = '000' AND STKM8.SHOPCD = '000' AND STKM8.SETTEINO = '046' AND STKM8.RCRDKBN = 'M' AND STKM8.SETTEICD = TKSM.TAIKAIRIYUKBN ) LEFT OUTER JOIN S02M006T STKM9 ON ( STKM9.APKIHONCD = '000' AND STKM9.SHOPCD = '000' AND STKM9.SETTEINO = '045' AND STKM9.RCRDKBN = 'M' AND STKM9.SETTEICD = TKSM.CHUITOKUISAKIKBNAP ) LEFT OUTER JOIN S02M006T STKM10 ON ( STKM10.APKIHONCD = '000' AND STKM10.SHOPCD = '000' AND STKM10.SETTEINO = '140' AND STKM10.RCRDKBN = 'M' AND STKM10.SETTEICD = TKSM.TOKUBETSUUNTKBN ) LEFT OUTER JOIN S02M018T HTAM ON ( HTAM.APKIHONCD = TKSM.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = TKSM.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = TKSM.DLVRYKANKATSUKYOTENCD AND HTAM.DLVRYAREACD = TKSM.DLVRYAREACD AND #{unyodate, jdbcType=VARCHAR} BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD AND HTAM.YUKOKBN = '1' ) LEFT OUTER JOIN S02M020T EIAM ON ( EIAM.APKIHONCD = TKSM.APKIHONCD AND EIAM.SHOPCD = TKSM.SHOPCD AND EIAM.EIGYOAREACD = TKSM.EIGYOAREACD ) LEFT OUTER JOIN S02M047T JGSM ON ( JGSM.APKIHONCD = TKSM.APKIHONCD AND JGSM.SHOPCD = TKSM.SHOPCD AND JGSM.JIGYOSHOCD = TKSM.JIGYOSHOCD ) LEFT OUTER JOIN S01M004T CNDM1 ON ( CNDM1.CONDITIONID = 'CN100' AND TKSM.TOKUISAKIKBN = CNDM1.SETTEIATAI ) LEFT OUTER JOIN S01M004T CNDM2 ON ( CNDM2.CONDITIONID = 'CN206' AND TKSM.JUTAKUDLVRYCSTKBN = CNDM2.SETTEIATAI ) LEFT OUTER JOIN S01M004T CNDM3 ON ( CNDM3.CONDITIONID = 'CN085' AND SKSM.TAIRYUKBN = CNDM3.SETTEIATAI ) LEFT OUTER JOIN S01M004T CNDM4 ON ( CNDM4.CONDITIONID = 'CN042' AND TKSM.DLVRYKBN = CNDM4.SETTEIATAI ) LEFT OUTER JOIN S01M004T CNDM5 ON ( CNDM5.CONDITIONID = 'CN041' AND TKSM.ACPTRCPTKBN = CNDM5.SETTEIATAI ) LEFT OUTER JOIN S01M004T CNDM6 ON ( CNDM6.CONDITIONID = 'CN001' AND TKSM.YUKOKBN = CNDM6.SETTEIATAI ) WHERE
1 = 1
