AND ( TKSM.TOKUISAKINMN1 LIKE '%' || #{tokuisakinmn, jdbcType=VARCHAR} || '%' OR TKSM.TOKUISAKINMN2 LIKE '%' || #{tokuisakinmn, jdbcType=VARCHAR} || '%' )
AND ( TKSM.TOKUISAKINMKANAN1 LIKE '%' || #{tokuisakinmkanan} || '%' OR TKSM.TOKUISAKINMKANAN2 LIKE '%' || #{tokuisakinmkanan} || '%' )
AND ( REPLACE(TKSM.CLCKENSAKUYOTELNON1, '-', '') = REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', '') OR REPLACE(TKSM.CLCKENSAKUYOTELNON2, '-', '') = REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', '') OR REPLACE(TKSM.CLCKENSAKUYOTELNON3, '-', '') = REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', '') OR REPLACE(TKSM.CLCKENSAKUYOTELNON4, '-', '') = REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', '') )
AND ( REPLACE(TKSM.RENRAKUSAKINON1, '-', '') LIKE CONCAT('%', CONCAT(REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', ''), '%')) OR REPLACE(TKSM.RENRAKUSAKINON2, '-', '') LIKE CONCAT('%', CONCAT(REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', ''), '%')) OR REPLACE(TKSM.RENRAKUSAKINON3, '-', '') LIKE CONCAT('%', CONCAT(REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', ''), '%')) OR REPLACE(TKSM.RENRAKUSAKINON4, '-', '') LIKE CONCAT('%', CONCAT(REPLACE(#{renrakusakinon, jdbcType=VARCHAR}, '-', ''), '%')) )
AND TKSM.YUBINNO LIKE #{yubinno, jdbcType=VARCHAR} || '%'
