#{item}
AND TKSM.SKYSAKICD LIKE #{skysakicd, jdbcType=VARCHAR} || '%'
AND TKSM.TOKUISAKIGAIBUSKBTSCD LIKE #{gaibuskbtscd1, jdbcType=VARCHAR} || '%'
AND TKSM.TOKUISAKIGAIBUSKBTSCD2 LIKE #{gaibuskbtscd2, jdbcType=VARCHAR} || '%'
AND TKSM.TOKUISAKIGAIBUSKBTSCD3 LIKE #{gaibuskbtscd3, jdbcType=VARCHAR} || '%'
AND TKSM.COLLABOKBN = #{collabokbn, jdbcType=VARCHAR}
AND TKSM.MOSHIKOMIRCPTDD BETWEEN #{moshikomircptddstr, jdbcType=VARCHAR} AND #{moshikomircptddend, jdbcType=VARCHAR}
AND TKSM.MOSHIKOMIRCPTDD >= #{moshikomircptddstr, jdbcType=VARCHAR}
AND TKSM.MOSHIKOMIRCPTDD <= #{moshikomircptddend, jdbcType=VARCHAR}
AND TKSM.SHOKAIWSVSTUPDD BETWEEN #{shokaiwsvstupddstr, jdbcType=VARCHAR} AND #{shokaiwsvstupddend, jdbcType=VARCHAR}
AND TKSM.SHOKAIWSVSTUPDD >= #{shokaiwsvstupddstr, jdbcType=VARCHAR}
AND TKSM.SHOKAIWSVSTUPDD <= #{shokaiwsvstupddend, jdbcType=VARCHAR}
AND TKSM.STARTUP = '1'
AND (TKSM.STARTUP = '0' OR TKSM.STARTUP IS NULL)
AND TKSM.NYUKAIDD BETWEEN #{nyukaiddstr, jdbcType=VARCHAR} AND #{nyukaiddend, jdbcType=VARCHAR}
AND TKSM.NYUKAIDD >= #{nyukaiddstr, jdbcType=VARCHAR}
AND TKSM.NYUKAIDD <= #{nyukaiddend, jdbcType=VARCHAR}
AND TKSM.TAIKAIDD BETWEEN #{taikaiddstr, jdbcType=VARCHAR} AND #{taikaiddend, jdbcType=VARCHAR}
AND TKSM.TAIKAIDD >= #{taikaiddstr, jdbcType=VARCHAR}
AND TKSM.NYUKAIDD <= #{taikaiddend, jdbcType=VARCHAR}
AND TSJT.SAISHUACPTDD BETWEEN #{saishuacptddstr, jdbcType=VARCHAR} AND #{saishuacptddend, jdbcType=VARCHAR}
AND TSJT.SAISHUACPTDD >= #{saishuacptddstr, jdbcType=VARCHAR}
AND TSJT.SAISHUACPTDD <= #{saishuacptddend, jdbcType=VARCHAR}
AND TKSM.WSVHIKIAGEDD BETWEEN #{hikiageddstr, jdbcType=VARCHAR} AND #{hikiageddend, jdbcType=VARCHAR}
AND TKSM.WSVHIKIAGEDD >= #{hikiageddstr, jdbcType=VARCHAR}
AND TKSM.WSVHIKIAGEDD <= #{hikiageddend, jdbcType=VARCHAR}
AND TKSM.KEIZOKURNK = #{keizokurnk, jdbcType=VARCHAR}
AND TKSM.APBETSUTOKUISAKIRNK = #{apbetsutokuisakirnk, jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN = #{tokuisakikbn, jdbcType=VARCHAR}
AND TKSM.SHOHIRNK = #{shohirnk, jdbcType=VARCHAR}
AND SKSM.TAIRYUKBN = #{tairyukbn, jdbcType=VARCHAR}
AND TKSM.EIGYOAREACD = #{eigyoareacd, jdbcType=VARCHAR}
AND TKSM.DLVRYKANKATSUKYOTENCD = #{dlvrykyotencd, jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUAPKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUSHOPCD = #{shopcd, jdbcType=VARCHAR}
AND TKSM.DLVRYAREACD = #{dlvryareacd, jdbcType=VARCHAR}
AND TKSM.RCPTKBN = #{rcptkbn, jdbcType=VARCHAR}
AND TKSM.BAITAIKBN = #{baitaikbn, jdbcType=VARCHAR}
AND TKSM.KAKUTOKUKBN = #{kakutokukbn, jdbcType=VARCHAR}
AND TKSM.HANSOKUSHSCD = #{kakutokushscd, jdbcType=VARCHAR}
AND TKSM.EIGYOTNSHACD = #{eigyotnshacd, jdbcType=VARCHAR}
AND TKSM.DLVRYTNSHACD = #{dlvrytnshacd, jdbcType=VARCHAR}
AND TKSM.CDKINDKBN = #{cdkindkbn, jdbcType=VARCHAR}
AND TKSM.GYOSHUKBN = #{gyoshukbn, jdbcType=VARCHAR}
AND TKSM.ACPTRCPTKBN = #{acptrcptkbn, jdbcType=VARCHAR}
AND TKSM.MTMKISVKBN = #{mtmkisvkbn, jdbcType=VARCHAR}
AND TKSM.MURYOBTLSVKBN = #{muryobtlsvkbn, jdbcType=VARCHAR}
AND TKSM.TOKUISAKISHUKEICD LIKE '%' || #{tokuisakishukeicd, jdbcType=VARCHAR} || '%'
AND TKSM.JUTAKUDLVRYCSTKBN = #{jutakudlvrycstkbn, jdbcType=VARCHAR}
AND TKSM.TOKUISAKISHOPCD = #{tokuisakishopcd, jdbcType=VARCHAR}
AND TKSM.KAKUTOKUEJNTCD = #{ejntcd, jdbcType=VARCHAR}
AND TKSM.KAIINCD LIKE #{kaiincd, jdbcType=VARCHAR} || '%'
AND TKSM.GYOSHUSHSKBN = #{gyoshushskbn, jdbcType=VARCHAR}
AND TKSM.ITAKUAITEAPKIHONCD = #{itakuaiteapkihoncd, jdbcType=VARCHAR}
AND TKSM.ITAKUAITESHOPCD = #{itakuaiteshopcd, jdbcType=VARCHAR}
AND TKSM.ITAKUAITETOKUISAKICD = #{itakuaitetokuisakicd, jdbcType=VARCHAR}
AND TKSM.RKNKINDKIHONFLG = '1'
AND TKSM.RKNKINDTOKUBETSUUNTFLG = '1' AND TKSM.RKNKINDTOKUBETSUNEBIKIFLG = '0'
AND TKSM.RKNKINDTOKUBETSUNEBIKIFLG = '1' AND TKSM.RKNKINDTOKUBETSUUNTFLG = '0'
AND TKSM.RKNKINDTOKUBETSUUNTFLG = '1' AND TKSM.RKNKINDTOKUBETSUNEBIKIFLG = '1'
AND TKSM.PLNCD = #{rknplncd, jdbcType=VARCHAR}
AND TKSM.KAKUTOKUHONBUKYNPNCD = #{kakutokuhonbukynpncd, jdbcType=VARCHAR}
AND TKSM.KAKUTOKUKYNPNCD = #{kakutokukynpncd, jdbcType=VARCHAR}
AND TKSM.JISHASVCD = #{jishasvcd, jdbcType=VARCHAR}
AND TKSM.RIYOMOKUTEKIKBN = #{riyomokutekikbn, jdbcType=VARCHAR}
AND TKSM.NESTLEHACHUSAKIKBN = #{nestlehachusakikbn, jdbcType=VARCHAR}
AND EXISTS ( SELECT * FROM S02M048T TSMST WHERE TSMST.APKIHONCD = TKSM.APKIHONCD AND TSMST.SHOPCD = TKSM.SHOPCD AND TSMST.TOKUISAKICD = TKSM.TOKUISAKICD AND TSMST.HIKIAGEDD IS NULL AND TSMST.YUKOKBN = '1'
AND TSMST.JIKAIMNTYTIDYDM = #{jikaimntytidydm, jdbcType=VARCHAR}
AND TSMST.WSVKISHUCD = #{wsvkishucd, jdbcType=VARCHAR}
)
ORDER BY TKSM.APKIHONCD, TKSM.SHOPCD, TKSM.TOKUISAKICD )
WHERE ROWNUM <= #{rownum} +1

SELECT COUNT(1) CNT FROM ( SELECT TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.TOKUISAKICD , TKSM.JOTAISTS FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) LEFT JOIN S02M047T JGSM ON ( JGSM.APKIHONCD = TKSM.APKIHONCD AND JGSM.SHOPCD = TKSM.SHOPCD AND JGSM.JIGYOSHOCD = TKSM.JIGYOSHOCD ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN IN
#{tokuisakikbnlist}
) TKS LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD_UR , TKSM.SHOPCD SHOPCD_UR , TKSM.TOKUISAKICD TOKUISAKICD_UR , SUM( CASE WHEN URMT.SHNCD IN ( SELECT RGR.SHNCD FROM S02M007T RGR WHERE RGR.APKIHONCD(+) = '001' AND STKBN(+) = '0' AND LCTGRYCD(+) = '01' AND MCTGRYCD(+) = '001' AND SCTGRYCD(+) = '001' AND YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) RGRAYURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT RGR.SHNCD FROM S02M007T RGR WHERE RGR.APKIHONCD(+) = '001' AND STKBN(+) = '0' AND LCTGRYCD(+) = '01' AND MCTGRYCD(+) = '001' AND SCTGRYCD(+) = '001' AND YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) RGRAMURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT SRM.SHNCD FROM S02M007T SRM WHERE SRM.APKIHONCD(+) = '001' AND SRM.STKBN(+) = '0' AND SRM.LCTGRYCD(+) = '01' AND SRM.MCTGRYCD(+) = '001' AND SRM.SCTGRYCD(+) = '002' AND SRM.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SRMYURYO , SUM( CASE WHEN URMT.SHNCD IN ( SELECT SRM.SHNCD FROM S02M007T SRM WHERE SRM.APKIHONCD(+) = '001' AND SRM.STKBN(+) = '0' AND SRM.LCTGRYCD(+) = '01' AND SRM.MCTGRYCD(+) = '001' AND SRM.SCTGRYCD(+) = '002' AND SRM.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SRMMURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) AND URMT.SHNCD NOT IN ( SELECT SNT.SHNCD FROM S02M007T SNT WHERE SNT.APKIHONCD(+) = '001' AND SNT.STKBN(+) = '0' AND SNT.LCTGRYCD(+) = '01' AND SNT.MCTGRYCD(+) = '001' AND SNT.SCTGRYCD IN ('001', '002') AND SNT.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SONOTAYURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) AND URMT.SHNCD NOT IN ( SELECT SNT.SHNCD FROM S02M007T SNT WHERE SNT.APKIHONCD(+) = '001' AND SNT.STKBN(+) = '0' AND SNT.LCTGRYCD(+) = '01' AND SNT.MCTGRYCD(+) = '001' AND SNT.SCTGRYCD IN ('001', '002') AND SNT.YUKOKBN(+) = '1' ) AND URMT.KEIJOKBN NOT IN ('01', '02') THEN URMT.SURYO ELSE 0 END ) SONOTAMURYO , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT WTR.MOJISETTEIATAI FROM S02M006T WTR WHERE WTR.APKIHONCD(+) = '000' AND WTR.SHOPCD(+) = '000' AND WTR.SETTEINO(+) = '096' AND WTR.RCRDKBN(+) = 'M' AND WTR.SETTEICD(+) = '1' AND WTR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SEIHINMIZUURI , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD IN ( SELECT SVR.MOJISETTEIATAI FROM S02M006T SVR WHERE SVR.APKIHONCD(+) = '000' AND SVR.SHOPCD(+) = '000' AND SVR.SETTEINO(+) = '096' AND SVR.RCRDKBN(+) = 'M' AND SVR.SETTEICD(+) = '2' AND SVR.SETTEICD IN ('2', '3') AND SVR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) RTLRKN , SUM( CASE WHEN URMT.TANPINMEISAIFLG = '1' AND URMT.LCTGRYCD NOT IN ( SELECT SNT.MOJISETTEIATAI FROM S02M006T SNT WHERE SNT.APKIHONCD(+) = '000' AND SNT.SHOPCD(+) = '000' AND SNT.SETTEINO(+) = '096' AND SNT.RCRDKBN(+) = 'M' AND SNT.SETTEICD IN ('1', '2', '3') AND SNT.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) SONOTAURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHOHITAXKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.KIN ELSE 0 END ) KONKAISHUNODAIKOURIKIN , SUM( CASE WHEN URMT.NYURYOKUMEISAIFLG = '1' AND URMT.LCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '096' AND HKR.RCRDKBN(+) = ' M ' AND HKR.SETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) AND URMT.MCTGRYCD = ( SELECT HKR.MOJISETTEIATAI FROM S02M006T HKR WHERE HKR.APKIHONCD(+) = '000' AND HKR.SHOPCD(+) = '000' AND HKR.SETTEINO(+) = '918' AND HKR.RCRDKBN(+) = 'M' AND HKR.SETTEICD(+) = '2' AND HKR.OYASETTEINO(+) = '096' AND HKR.OYASETTEICD(+) = '8' AND HKR.YUKOKBN(+) = '1' ) THEN URMT.SHOHITAXKIN ELSE 0 END ) KONKAISHUNODAIKOSHOHITAXKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S06T001T URHT ON ( URHT.APKIHONCD = TKSM.APKIHONCD AND URHT.SHOPCD = TKSM.SHOPCD AND URHT.TOKUISAKICD = TKSM.TOKUISAKICD AND URHT.GETSUJIPRCSJISSIDD = '00000000' AND URHT.URIDD <= #{nextdydm,jdbcType=VARCHAR} || SHPM.SHIMEDD AND URHT.YUKOKBN = '1' ) INNER JOIN S06T002T URMT ON ( URMT.APKIHONCD = URHT.APKIHONCD AND URMT.SHOPCD = URHT.SHOPCD AND URMT.URIDNPYNO = URHT.URIDNPYNO AND URMT.EDANO = URHT.EDANO AND URMT.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN IN
#{tokuisakikbnlist}
GROUP BY TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.TOKUISAKICD ) URI ON ( URI.APKIHONCD_UR = TKS.APKIHONCD AND URI.SHOPCD_UR = TKS.SHOPCD AND URI.TOKUISAKICD_UR = TKS.TOKUISAKICD ) LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD_NK , TKSM.SHOPCD SHOPCD_NK , TKSM.TOKUISAKICD TOKUISAKICD_NK , SUM( NVL(NKMT.NYKNKIN, 0) + NVL(NKMT.NEBIKIKIN, 0) + NVL(NKMT.TESURYO, 0) ) KONKAINYKNKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S10T001T NKMT ON ( NKMT.APKIHONCD = TKSM.APKIHONCD AND NKMT.SHOPCD = TKSM.SHOPCD AND NKMT.TOKUISAKICD = TKSM.TOKUISAKICD AND NKMT.GETSUJIPRCSJISSIDD = '00000000' AND NKMT.NYKNDD <= #{nextdydm,jdbcType=VARCHAR} || SHPM.SHIMEDD AND NKMT.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN IN
#{tokuisakikbnlist}
GROUP BY TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.TOKUISAKICD ) NK ON ( NK.APKIHONCD_NK = TKS.APKIHONCD AND NK.SHOPCD_NK = TKS.SHOPCD AND NK.TOKUISAKICD_NK = TKS.TOKUISAKICD ) LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD_ZD , TKSM.SHOPCD SHOPCD_ZD , TKSM.TOKUISAKICD TOKUISAKICD_ZD , SUM(NVL(UZDT.KURIKOSHIKIN, 0)) ZNKKURIKOSHIKIN FROM S02M013T TKSM INNER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.SHOPCD AND SHPM.YUKOKBN = '1' ) INNER JOIN S07T002T UZDT ON ( UZDT.APKIHONCD = TKSM.APKIHONCD AND UZDT.SHOPCD = TKSM.SHOPCD AND UZDT.TOKUISAKICD = TKSM.TOKUISAKICD AND UZDT.SHIMEDYDM = SUBSTRB(SHPM.URIGETSUJIDYDMDD, 1, 6) AND UZDT.SHIMEDD = SUBSTRB(SHPM.URIGETSUJIDYDMDD, 7, 2) AND UZDT.YUKOKBN = '1' ) WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TKSM.RIYOWSVKBN = #{riyowsvkbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshosentaku,jdbcType=VARCHAR}
AND TKSM.TOKUISAKIKBN IN
#{tokuisakikbnlist}
GROUP BY TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.TOKUISAKICD ) ZD ON ( ZD.APKIHONCD_ZD = TKS.APKIHONCD AND ZD.SHOPCD_ZD = TKS.SHOPCD AND ZD.TOKUISAKICD_ZD = TKS.TOKUISAKICD ) WHERE ( URI.TOKUISAKICD_UR IS NOT NULL OR NK.TOKUISAKICD_NK IS NOT NULL OR ZD.TOKUISAKICD_ZD IS NOT NULL )
AND NOT ( TKS.JOTAISTS IN ('02','06','10') AND ( URI.SEIHINMIZUURI = 0 AND URI.RTLRKN = 0 AND URI.SONOTAURIKIN = 0 AND URI.KONKAISHOHITAXKIN = 0 AND URI.KONKAISHUNODAIKOURIKIN = 0 AND URI.KONKAISHUNODAIKOSHOHITAXKIN = 0 AND ZD.ZNKKURIKOSHIKIN = 0 AND NK.KONKAINYKNKIN = 0 AND URI.RGRAYURYO = 0 AND URI.RGRAMURYO = 0 AND URI.SRMYURYO = 0 AND URI.SRMMURYO = 0 AND URI.SONOTAYURYO = 0 AND URI.SONOTAMURYO = 0 ) )

SELECT
    COUNT(*)
FROM
    S02M013T --得意先マスタ
WHERE
    APKIHONCD    =  #{apkihoncd,jdbcType=VARCHAR}
AND SHOPCD       =  #{shopcd,jdbcType=VARCHAR}
AND (    TOKUISAKIGAIBUSKBTSCD = #{tokuisakigaibuskbtscd,jdbcType=VARCHAR}
　　　　OR  TOKUISAKIGAIBUSKBTSCD2 = #{tokuisakigaibuskbtscd,jdbcType=VARCHAR}
     OR  TOKUISAKIGAIBUSKBTSCD3 = #{tokuisakigaibuskbtscd,jdbcType=VARCHAR}
    )

AND TOKUISAKICD  != #{tokuisakicd,jdbcType=VARCHAR}

    SELECT
        SUM(ADRCNT) AS ADRSUM    -- 住所が一致する件数
       ,SUM(TELCNT) AS TELSUM    -- 電話番号が一致する件数
    FROM
       (SELECT
            -- 住所一致判定
              -- ひらがなをカタカナに変換
              -- 半角カナを全角カナに変換（TO_MULTI_BYTEは半角カナは対象外）
              -- 半角文字を全角文字に変換
              -- 小文字を大文字に変換
            CASE WHEN UTL_I18N.TRANSLITERATE(UTL_I18N.TRANSLITERATE(TO_MULTI_BYTE(UPPER(REGEXP_REPLACE(ADRSN1, '([ 　])+', ''))),'hwkatakana_fwkatakana'),'hiragana_fwkatakana')
                LIKE UTL_I18N.TRANSLITERATE(UTL_I18N.TRANSLITERATE(TO_MULTI_BYTE(UPPER(#{adrsn1,jdbcType=VARCHAR})),'hwkatakana_fwkatakana'),'hiragana_fwkatakana')  || '%' 
                THEN 1 
                ELSE 0 
            END AS ADRCNT

            -- 連絡先一致判定
           ,CASE WHEN (
               
                       CLCKENSAKUYOTELNON1 = #{renrakusakinon1,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON2 = #{renrakusakinon1,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON3 = #{renrakusakinon1,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON4 = #{renrakusakinon1,jdbcType=VARCHAR}
    
    
                   OR
    
    
                       CLCKENSAKUYOTELNON1 = #{renrakusakinon2,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON2 = #{renrakusakinon2,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON3 = #{renrakusakinon2,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON4 = #{renrakusakinon2,jdbcType=VARCHAR}
    
    
                   OR
    
    
                       CLCKENSAKUYOTELNON1 = #{renrakusakinon3,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON2 = #{renrakusakinon3,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON3 = #{renrakusakinon3,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON4 = #{renrakusakinon3,jdbcType=VARCHAR}
    
    
                   OR
    
    
                       CLCKENSAKUYOTELNON1 = #{renrakusakinon4,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON2 = #{renrakusakinon4,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON3 = #{renrakusakinon4,jdbcType=VARCHAR}
                   OR  CLCKENSAKUYOTELNON4 = #{renrakusakinon4,jdbcType=VARCHAR}
    
            )
                THEN 1
                ELSE 0
            END AS TELCNT
        FROM
            -- カナ名が一致する注意顧客のみを抽出
            (SELECT * FROM S02M013T
            WHERE TOKUISAKIKBN = '1'
            AND   CHUITOKUISAKIKBNACI is not null
            AND   CHUITOKUISAKIKBNACI != '0'
            AND   REPLACE(TOKUISAKINMKANAN1, ' ') LIKE #{tokuisakinmkanan1,jdbcType=VARCHAR} || '%'    -- カナ名が一致
            )
        WHERE
            -- 住所一致判定
              -- ひらがなをカタカナに変換
              -- 半角カナを全角カナに変換（TO_MULTI_BYTEは半角カナは対象外）
              -- 半角文字を全角文字に変換
              -- 小文字を大文字に変換
            UTL_I18N.TRANSLITERATE(UTL_I18N.TRANSLITERATE(TO_MULTI_BYTE(UPPER(REGEXP_REPLACE(ADRSN1, '([ 　])+', ''))),'hwkatakana_fwkatakana'),'hiragana_fwkatakana')
                LIKE UTL_I18N.TRANSLITERATE(UTL_I18N.TRANSLITERATE(TO_MULTI_BYTE(UPPER(#{adrsn1,jdbcType=VARCHAR})),'hwkatakana_fwkatakana'),'hiragana_fwkatakana')  || '%'
        OR  (
      
                CLCKENSAKUYOTELNON1 = #{renrakusakinon1,jdbcType=VARCHAR}
            OR  CLCKENSAKUYOTELNON2 = #{renrakusakinon1,jdbcType=VARCHAR}
            OR  CLCKENSAKUYOTELNON3 = #{renrakusakinon1,jdbcType=VARCHAR}
