AKUSHO SHINSHNNMRYAKUSHO , DECODE(TKSM10.SHNCD, NULL, NULL, TKSM10.STUPDD) STUPDD , DECODE(TKSM10.SHNCD, NULL, NULL, TKSM10.JIKAIMNTYTIDYDM) JIKAIMNTYTIDYDM , ( SELECT COUNT(*) FROM S02M048T TSSM WHERE TSSM.APKIHONCD = TKSM10.APKIHONCD AND TSSM.SHOPCD = TKSM10.SHOPCD AND TSSM.TOKUISAKICD = TKSM10.TOKUISAKICD AND TSSM.SHNCD = TKSM10.SHNCD AND TSSM.HIKIAGEDD IS NULL AND TSSM.YUKOKBN = '1' ) WSVSTUPDAISUMEI , ( SELECT COUNT(*) FROM S02M048T TSSM2 WHERE TSSM2.APKIHONCD = TKSM10.APKIHONCD AND TSSM2.SHOPCD = TKSM10.SHOPCD AND TSSM2.TOKUISAKICD = TKSM10.TOKUISAKICD AND TSSM2.SHNCD <> TKSM10.SHNCD AND TSSM2.HIKIAGEDD IS NULL AND TSSM2.YUKOKBN = '1' ) WSVDAISUMEI FROM S02M013T TKSM LEFT JOIN S02M046T SHPM ON ( TKSM.APKIHONCD = SHPM.APKIHONCD AND TKSM.SHOPCD = SHPM.SHOPCD ) LEFT JOIN S02M047T JGSM ON ( TKSM.APKIHONCD = JGSM.APKIHONCD AND TKSM.SHOPCD = JGSM.SHOPCD AND TKSM.JIGYOSHOCD = JGSM.JIGYOSHOCD ) LEFT JOIN S02M003T TTSM ON ( TKSM.APKIHONCD = TTSM.APKIHONCD AND TKSM.SHOPCD = TTSM.SHOPCD AND TKSM.EIGYOTNSHACD = TTSM.TNSHACD ) LEFT JOIN S02M006T SYKM ON ( SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEINO = '014' AND SYKM.SETTEICD = TKSM.TOKUISAKIJOTAI ) LEFT JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEINO = '011' AND SYKM2.SETTEICD = TKSM.RENRAKUSAKINOKBNN1 ) LEFT JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEINO = '011' AND SYKM3.SETTEICD = TKSM.RENRAKUSAKINOKBNN2 ) LEFT JOIN S02M006T SYKM4 ON ( SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEINO = '011' AND SYKM4.SETTEICD = TKSM.RENRAKUSAKINOKBNN3 ) LEFT JOIN S02M006T SYKM5 ON ( SYKM5.APKIHONCD = '000' AND SYKM5.SHOPCD = '000' AND SYKM5.RCRDKBN = 'M' AND SYKM5.SETTEINO = '011' AND SYKM5.SETTEICD = TKSM.RENRAKUSAKINOKBNN4 ) LEFT JOIN ( SELECT S02M048T.APKIHONCD , S02M048T.SHOPCD , S02M048T.TOKUISAKICD , S02M048T.STUPWSVNO , S02M048T.SHNCD , S02M048T.STUPDD , S02M048T.JIKAIMNTYTIDYDM FROM S02M048T , ( SELECT APKIHONCD , SHOPCD , TOKUISAKICD , MIN(STUPWSVNO) STUPWSVNO FROM S02M048T WHERE HIKIAGEDD IS NULL AND APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHOPCD = #{shopcd,jdbcType=VARCHAR} AND YUKOKBN = '1' GROUP BY APKIHONCD , SHOPCD , TOKUISAKICD ) SUB1 WHERE S02M048T.APKIHONCD = SUB1.APKIHONCD AND S02M048T.SHOPCD = SUB1.SHOPCD AND S02M048T.TOKUISAKICD = SUB1.TOKUISAKICD AND S02M048T.STUPWSVNO = SUB1.STUPWSVNO ) TKSM10 ON ( TKSM10.APKIHONCD = TKSM.APKIHONCD AND TKSM10.SHOPCD = TKSM.SHOPCD AND TKSM10.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT JOIN S02V001T SHMV ON ( SHMV.APKIHONCD = TKSM10.APKIHONCD AND SHMV.SHOPCD = TKSM10.SHOPCD AND SHMV.SHNCD = TKSM10.SHNCD ) JOIN S02M017T SKSM ON ( TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD ) JOIN S02M050T TJST ON ( TJST.APKIHONCD = TKSM.APKIHONCD AND TJST.SHOPCD = TKSM.SHOPCD AND TJST.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT JOIN S01M004T TAIRYUKBNNM ON ( TAIRYUKBNNM.CONDITIONID = 'CN085' AND TAIRYUKBNNM.SETTEIATAI = SKSM.TAIRYUKBN ) LEFT JOIN S01M004T JUTAKUDLVRYCSTKBNNM ON ( JUTAKUDLVRYCSTKBNNM.CONDITIONID = 'CN206' AND JUTAKUDLVRYCSTKBNNM.SETTEIATAI = TKSM.JUTAKUDLVRYCSTKBN ) WHERE TJST.ZNKDLVRYDNPYNO IS NOT NULL AND TJST.YUKOKBN = '1' AND TKSM.TOKUISAKIJOTAI IN ('3', '5') AND TKSM.TOKUISAKIKBN = '1' AND TKSM.KYUMINKANRI = '1'
