M.TOKUISAKICD ) LEFT JOIN S02V001T SHMV ON ( SHMV.APKIHONCD = TKSM10.APKIHONCD AND SHMV.SHOPCD = TKSM10.SHOPCD AND SHMV.SHNCD = TKSM10.SHNCD ) JOIN S02M017T SKSM ON ( TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD ) JOIN S02M050T TJST ON ( TJST.APKIHONCD = TKSM.APKIHONCD AND TJST.SHOPCD = TKSM.SHOPCD AND TJST.TOKUISAKICD = TKSM.TOKUISAKICD ) WHERE TJST.ZNKDLVRYDNPYNO IS NOT NULL AND TJST.YUKOKBN = '1' AND TKSM.TOKUISAKIJOTAI IN ('3', '5') AND TKSM.TOKUISAKIKBN = '1' AND TKSM.KYUMINKANRI = '1'
